{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "It defines an \"immigration officer\" as any state, local, or federal law enforcement officer who is seeking to enforce immigration law. The definition includes, but is not limited to, U.S. Immigration and Customs Enforcement officers and U.S. Customs and Border Protection officers.",
      "rationale": "Conveys the definition's enforcement purpose, all three levels of law enforcement, and both illustrative federal agencies."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "Under the bill, if an immigration officer is present on the grounds of a public school run by an LEA, or on the grounds of a public charter school, the director of schools or the director of the charter school would have to notify people right away. Those to be notified are all students enrolled in the LEA or charter school, their parents, and all educators, employees, and contractors. This duty would apply despite Title 4, chapter 42 and Title 7, chapter 68 of the Tennessee Code, which are the chapters referred to in the bill's sanctuary policy provisions.",
      "rationale": "Identifies the responsible directors, immediate notification requirement, triggering presence on school grounds, all required recipients, and the override of the specified chapters."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "The bill also says that this notice requirement, and any policy a local school board or charter school governing body adopts to carry it out, is not a sanctuary policy. As a result, board or governing body members, school directors, and LEA or charter school employees would not face the penalties in those two chapters for adopting or enforcing a sanctuary policy.",
      "rationale": "Conveys both the non-sanctuary classification and protection against sanctuary-policy penalties for the covered officials and employees. In context, school directors encompasses both LEA and charter school directors; the omitted subsection citations are nonessential."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "The bill would take effect as soon as it becomes law.",
      "rationale": "States the effective date accurately."
    }
  ]
}
